// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0));
        amount = bound(amount, 0, type(uint256).max / 4);
        vm.deal(actor, amount + 1);
        uint256 before = c.depositsCount();
        vm.prank(actor);
        (bool ok,) = address(c).call{value: amount}("");
        assertTrue(ok);
        // Rule: every successful deposit via receive increases depositsCount by exactly one.
        assertTrue(c.depositsCount() == before + 1, "deposit must increment counter by exactly 1");
    }
}
